from pathlib import Path
import html
import json

ROOT = Path(__file__).parent
PAGES = {
    'index.html': ('Home', 'Auto repair built around clarity', 'Diagnostics, maintenance and repair pathways for a fictional Pittsburgh-area shop.'),
    'services.html': ('Services', 'Know what your car needs', 'Explore diagnostics, brakes, maintenance and repair services before requesting a visit.'),
    'process.html': ('Our Process', 'A clearer road from concern to repair', 'See how a real shop can document inspection, estimate approval, work and follow-up.'),
    'service-areas.html': ('Service Areas', 'A local shop for your everyday drive', 'Sample Pittsburgh and South Hills location content, ready for a verified client address and hours.'),
    'request-service.html': ('Request Service', 'Tell us what is happening', 'Preview a vehicle-specific service request. This demo does not send or save inquiries.'),
}

NAV = [('index.html','Home'),('services.html','Services'),('process.html','How it works'),('service-areas.html','Service area'),('request-service.html','Request service')]

def link(href, label, cls=''):
    return f'<a href="{href}" class="{cls}">{label}</a>'

def head(path, title, description):
    desc = html.escape(description, quote=True)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Northline Auto Works — Demo</title><meta name="description" content="{desc}"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#111c22"><meta property="og:type" content="website"><meta property="og:title" content="{title} | Northline Auto Works — Demo"><meta property="og:description" content="{desc}"><meta property="og:image" content="/assets/auto-repair-hero.webp"><meta name="twitter:card" content="summary_large_image"><link rel="canonical" href="https://fireworks-auto-repair.vercel.app/{'' if path == 'index.html' else path}"><link rel="stylesheet" href="/styles.css"><script src="/script.js" defer></script><script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@type':'WebPage','name':title+' | Northline Auto Works — fictional demo','description':description,'isPartOf':{'@type':'WebSite','name':'Northline Auto Works — fictional demo'}})}</script></head>'''

def shell(path, body):
    title, _, desc = PAGES[path]
    nav = ''.join(link(href,label,'active' if href == path else '') for href,label in NAV)
    return head(path,title,desc)+f'''<body><div class="demo">FIREWORKS WEBSITE DEMO · FICTIONAL BUSINESS · NO REQUESTS SENT OR STORED</div><a class="skip" href="#main">Skip to content</a><header class="header wrap"><a class="brand" href="/" aria-label="Northline Auto Works home"><span class="mark">N<span>·</span></span><span>NORTHLINE<small>AUTO WORKS / DEMO</small></span></a><button class="menu" aria-controls="nav" aria-expanded="false" aria-label="Toggle navigation">Menu <span aria-hidden="true">☰</span></button><nav id="nav" aria-label="Main navigation">{nav}</nav></header><main id="main">{body}</main><footer class="footer"><div class="wrap footgrid"><div><div class="brand"><span class="mark">N<span>·</span></span><span>NORTHLINE<small>AUTO WORKS / DEMO</small></span></div><p>An adaptable auto repair website system. All names, locations, imagery and workflows are examples.</p></div><div><h3>Explore</h3><a href="/services.html">Services</a><a href="/process.html">How it works</a><a href="/request-service.html">Service request</a></div><div><h3>At client launch</h3><p>Replace this sample region with verified address, phone, hours, qualifications, policies and booking provider.</p></div></div><div class="wrap bottom">© 2026 Northline Auto Works — fictional demo <span>No forms transmit, store or confirm appointments.</span></div></footer></body></html>'''

home = '''<section class="hero"><img src="/assets/auto-repair-hero.webp" alt="Illustrative generated image of a mechanic inspecting a vehicle in a workshop" width="2048" height="768" fetchpriority="high"><div class="hero-overlay"></div><div class="wrap hero-text"><p class="eyebrow">PITTSBURGH AUTO REPAIR · FICTIONAL DEMO</p><h1>Back on the road.<br><em>With a plan.</em></h1><p>Understand the concern. Choose the right service. Get a clear next step before anyone picks up a wrench.</p><div class="actions"><a class="button" href="/request-service.html">Start a service request <span>↗</span></a><a class="button ghost" href="/services.html">Explore services</a></div></div><div class="hero-note">Generated illustrative photography · not a real shop or customer vehicle</div></section>
<section class="rail"><div class="wrap railgrid"><span>01 / TELL US WHAT YOU NOTICE</span><span>02 / REVIEW THE SERVICE</span><span>03 / CONFIRM WITH A REAL SHOP</span></div></section>
<section class="section wrap"><div class="section-head"><div><p class="eyebrow">GOOD REPAIR STARTS WITH GOOD INFORMATION</p><h2>The right conversation,<br>from the first click.</h2></div><p>This template gives drivers a direct path to describe the vehicle and concern, while a real business can set its own inspection, estimate and scheduling policies.</p></div><div class="cards"><a class="card" href="/services.html#diagnostics"><span>01 / DIAGNOSTICS</span><h3>Something feel off?</h3><p>Warning lights, unusual sounds and drivability concerns start with an inspection plan.</p><strong>Explore diagnostics ↗</strong></a><a class="card" href="/services.html#brakes"><span>02 / BRAKES</span><h3>Know when to check.</h3><p>Describe noise, feel or wear before the actual shop advises on an inspection.</p><strong>Explore brake service ↗</strong></a><a class="card" href="/services.html#maintenance"><span>03 / MAINTENANCE</span><h3>Stay ahead of the next mile.</h3><p>Routine care based on the vehicle, usage and manufacturer guidance.</p><strong>Explore maintenance ↗</strong></a></div></section>
<section class="feature"><div class="wrap feature-grid"><div class="feature-image"><img src="/assets/auto-repair-hero.webp" alt="Generated example of a technician inspecting an engine bay" loading="lazy" width="2048" height="768"></div><div><p class="eyebrow">A SERVICE PROCESS WITH NO GUESSWORK</p><h2>See the work.<br>Understand the why.</h2><p>A strong repair shop website should explain what happens after a request: inspection, an estimate to approve, the work, and a follow-up. A client sets the real policies and timelines.</p><a class="text-link" href="/process.html">See the sample process ↗</a></div></div></section>
<section class="section wrap"><div class="section-head"><div><p class="eyebrow">BUILT FOR REAL CUSTOMER QUESTIONS</p><h2>Confidence is in<br>the details.</h2></div><p>Service pages, a visible process, location guidance, and vehicle-specific intake help visitors decide whether the shop is right for them.</p></div><div class="benefits"><div><b>Service clarity</b><p>Explain diagnostic and repair scope without implying a price or fix before inspection.</p></div><div><b>Vehicle-specific intake</b><p>Ask for year, make, model, concern, timing and preferred contact path.</p></div><div><b>Honest local context</b><p>Use verified address, hours and service radius at client launch.</p></div></div></section>
<section class="cta"><div class="wrap cta-grid"><div><p class="eyebrow">READY FOR THE NEXT STEP?</p><h2>Tell us about<br>your vehicle.</h2><p>Preview the request a customer would make. This demonstration does not contact a shop.</p></div><a class="button light" href="/request-service.html">Preview service request ↗</a></div></section>'''

def intro(kicker,title,text): return f'<section class="page-intro wrap"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p>{text}</p></section>'

services=intro('SERVICE PATHWAYS / SAMPLE CONTENT','Care for the miles ahead.','Specific pages and services can be tailored to the work a real shop actually performs. No repairs, guarantees or prices are represented as live offers.')+'''<section class="wrap service-list"><article id="diagnostics"><span>01 / DIAGNOSTICS</span><div><h2>Understand the concern.</h2><p>Warning lights, noises, starting issues and changes in how a vehicle drives call for a defined diagnostic process. A client supplies the actual equipment and inspection scope.</p><a href="/request-service.html?service=Diagnostics">Request a diagnostic conversation ↗</a></div></article><article id="brakes"><span>02 / BRAKE SERVICE</span><div><h2>Check what matters.</h2><p>Brake noises, vibration and changes in pedal feel deserve a careful inspection. Replacement recommendations and final costs depend on actual findings.</p><a href="/request-service.html?service=Brakes">Ask about brake service ↗</a></div></article><article id="maintenance"><span>03 / ROUTINE MAINTENANCE</span><div><h2>Plan the next interval.</h2><p>Oil and filter service, fluid checks and routine inspections should reflect the vehicle and manufacturer guidance. Replace this list with the shop's verified offerings.</p><a href="/request-service.html?service=Maintenance">Ask about maintenance ↗</a></div></article><article id="repairs"><span>04 / REPAIR WORK</span><div><h2>Approve a clear scope.</h2><p>After diagnosis, a real shop can describe recommended work, parts, pricing and timing for approval. This example makes no promises about specific repairs.</p><a href="/request-service.html?service=Repairs">Describe a repair concern ↗</a></div></article></section><section class="cta"><div class="wrap cta-grid"><div><p class="eyebrow">NOT SURE WHICH SERVICE FITS?</p><h2>Start with the symptom.</h2></div><a class="button light" href="/request-service.html">Preview an inquiry ↗</a></div></section>'''

process=intro('HOW IT WORKS / EXAMPLE','A repair process you can follow.','Show drivers what happens next, from an initial concern to a final walkthrough. The actual business sets inspection fees, authorization and warranty terms.')+'''<section class="wrap steps"><article><span>01</span><div><h2>Tell us what you notice.</h2><p>Share the vehicle, mileage, symptoms and preferred time. The demo form stays in your browser.</p></div></article><article><span>02</span><div><h2>Get an inspection plan.</h2><p>A real shop decides how it schedules an inspection, explains diagnostic fees and communicates findings.</p></div></article><article><span>03</span><div><h2>Review and approve.</h2><p>Present parts, labor, timing and any alternatives. Do not begin additional work without the client's defined authorization process.</p></div></article><article><span>04</span><div><h2>Drive away informed.</h2><p>Explain what was completed, future maintenance, and any real warranty terms in plain language.</p></div></article></section><section class="section wrap"><p class="eyebrow">POLICIES TO CUSTOMIZE</p><h2>Clear terms before a visit.</h2><div class="benefits"><div><b>Inspection fees</b><p>Add the shop's actual fees and when they apply.</p></div><div><b>Parts and warranties</b><p>Only publish verified product coverage and exclusions.</p></div><div><b>Transportation and timing</b><p>Confirm drop-off, shuttle, loaner and turnaround policies before claiming them.</p></div></div></section>'''

areas=intro('LOCAL DISCOVERY / SAMPLE REGION','Rooted in a real place.','Pittsburgh and South Hills references below are sample service-area context. Replace them with the verified address, neighborhoods, hours and contact details for the actual shop.')+'''<section class="wrap area-grid"><div><p class="eyebrow">SAMPLE LOCATION CONTEXT</p><h2>Pittsburgh &amp; the South Hills</h2><p>A driver may compare shops near Pittsburgh, Mt. Lebanon, Dormont, Carnegie and surrounding communities. A real shop should state its actual street address and realistic service model rather than generating repetitive city pages.</p></div><div class="area-card"><span>CLIENT DETAILS REQUIRED</span><dl><dt>Address</dt><dd>Client-verified shop location</dd><dt>Phone</dt><dd>Client-verified public phone</dd><dt>Hours</dt><dd>Client-verified operating hours</dd><dt>Service model</dt><dd>Drop-off, appointments and transportation as confirmed</dd></dl></div></section><section class="cta"><div class="wrap cta-grid"><div><p class="eyebrow">SERVICE STARTS WITH CONTEXT</p><h2>Describe your vehicle.</h2></div><a class="button light" href="/request-service.html">Request service preview ↗</a></div></section>'''

request=intro('SAFE LOCAL PREVIEW','Start with the vehicle.','This form demonstrates the customer journey. It validates in your browser but does not send, store, email or book anything.')+'''<section class="wrap form-layout"><div class="form-copy"><h2>The details that help.</h2><p>Use concise, practical questions. A real shop chooses its scheduling provider and lead destination only after configuration and end-to-end testing.</p><ul><li>Vehicle and approximate mileage</li><li>The concern or requested service</li><li>Timing and the best way to reply</li></ul><div class="warning"><strong>Demo only</strong><p>No appointment is made and no emergency response is available from this website.</p></div></div><form id="service-form" class="form"><div class="form-grid"><label>Full name <input name="name" autocomplete="name" required maxlength="100"></label><label>Email <input type="email" name="email" autocomplete="email" required></label><label>Phone <input type="tel" name="phone" autocomplete="tel" required pattern="[0-9+() .-]{7,20}" title="Enter a reachable phone number"></label><label>ZIP code <input name="zip" inputmode="numeric" pattern="[0-9]{5}" title="Five-digit ZIP code" required></label><label>Year <input name="year" inputmode="numeric" pattern="(19|20)[0-9]{2}" placeholder="2018" required></label><label>Make and model <input name="vehicle" placeholder="Example: Toyota RAV4" required maxlength="100"></label><label>Approximate mileage <input name="mileage" inputmode="numeric" pattern="[0-9]{1,7}" placeholder="65000"></label><label>Service <select name="service" required><option value="">Choose a service</option><option>Diagnostics</option><option>Brakes</option><option>Maintenance</option><option>Repairs</option><option>Not sure yet</option></select></label><label>Preferred timing <select name="timing" required><option value="">Choose timing</option><option>As soon as practical</option><option>This week</option><option>Next week</option><option>Flexible</option></select></label><label>Preferred contact <select name="contact" required><option value="">Choose contact</option><option>Phone</option><option>Email</option></select></label></div><label>What are you noticing? <textarea name="concern" rows="5" required maxlength="1000" placeholder="Describe symptoms or the service you need. Do not include sensitive information."></textarea></label><label class="check"><input type="checkbox" name="demo" required> I understand this is a fictional demo; nothing is sent, stored, scheduled or monitored.</label><button class="button" type="submit">Preview request locally ↗</button><div id="form-result" role="status" aria-live="polite" tabindex="-1"></div></form></section>'''

for path, body in [('index.html',home),('services.html',services),('process.html',process),('service-areas.html',areas),('request-service.html',request)]:
    (ROOT/path).write_text(shell(path,body),encoding='utf-8')
print('Built',len(PAGES),'pages')
